<template><CustomerWorkShell title="商品与次数核销" :manager="manager" :domain-busy="writeoff.busy.value" active="scanning"><template #recovery><CustomerWorkWriteoffRecoveryPanel :operations="writeoff" /></template><template v-if="target"><view class="cw-card"><text class="cw-subtitle">订单 {{ target.order_no }}</text><text class="cw-scope">付款订单 {{ target.root_order_no }} · 买家 {{ target.uid===0?'匿名收银顾客':target.uid }} · {{ target.store_id?'门店 '+target.store_id:'平台' }}</text><text v-if="target.cashier_origin.eligible" class="cw-scope">收银创建与付款来源已核对。匿名买家和零金额保留真实事实。</text><text v-else-if="target.store_id===0" class="cw-scope">{{ customerWriteoffNotice(target.cashier_origin.reason) }}</text><text class="cw-scope">部分核销后原码立即失效；全部核销会完成订单。次数按当前有效窗口和剩余量核验。</text><text v-if="!target.actions.writeoff.available" class="cw-error">{{ customerWriteoffNotice(target.actions.writeoff.reason||target.readiness.reason) }}</text><button @tap="manager.go('writeoffRecords',{orderId:target.id,orderNo:target.order_no})">查看实际核销记录</button></view><view class="cw-card"><text class="cw-subtitle">{{ target.product_type===4?'次卡次数':'商品核销次数' }}</text><view class="cw-controls"><button :disabled="writeoff.busy.value||!target.actions.writeoff.available" @tap="selectAll">选择当前窗口内全部次数</button><button :disabled="writeoff.busy.value" @tap="quantities={}">清除选择</button></view><view v-for="item in target.carts" :key="item.cart_row_id" class="cw-cart" :data-writeoff-cart-row="item.cart_row_id"><image v-if="item.image" :src="item.image" class="cw-image" mode="aspectFill" /><view class="cw-stack cw-grow"><text>{{ item.product_name }}</text><text class="cw-muted">{{ item.sku }} · 购买 {{ item.cart_num }} 件 · 剩余 {{ item.write_surplus_times }} / {{ item.write_times }} 次</text><text class="cw-muted">有效窗口 {{ customerWriteoffTime(item.write_start) }} 至 {{ customerWriteoffTime(item.write_end) }}</text><text v-if="!inWindow(item)" class="cw-error">当前显示窗口尚未开始或已结束，请重新读取确认。</text><text v-if="item.sale_price.source==='unproven'" class="cw-error">{{ customerWriteoffNotice(item.sale_price.reason) }}</text><text v-else class="cw-scope">原成交快照已核对 · 下一次 ¥{{ item.sale_price.next_price }} · 全部剩余 ¥{{ item.sale_price.all_remaining_price }}</text><view class="cw-quantity"><checkbox :checked="(quantities[item.cart_row_id]||0)>0" :disabled="!selectable(item)" @tap="toggle(item)" /><button :disabled="writeoff.busy.value||(quantities[item.cart_row_id]||0)<=1" @tap="change(item,-1)">−</button><input :value="quantities[item.cart_row_id]||0" type="number" :disabled="!selectable(item)" @input="set(item,$event)" /><button :disabled="!selectable(item)||(quantities[item.cart_row_id]||0)>=item.write_surplus_times" @tap="change(item,1)">＋</button></view></view></view><text class="cw-scope">本次金额按原成交快照逐项核验，不按商品现价推算。</text><button class="cw-full" :disabled="writeoff.busy.value||!target.actions.writeoff.available||!selected.length||!!error" @tap="execute">确认{{ allSelected?'全部剩余':'本次分次' }}核销（{{ total }} 次）</button></view></template><text v-if="error||writeoff.error.value" class="cw-error">{{ error||writeoff.error.value }}</text></CustomerWorkShell></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import CustomerWorkShell from '@/components/customerWork/CustomerWorkShell.vue';
import CustomerWorkWriteoffRecoveryPanel from '@/components/customerWork/CustomerWorkWriteoffRecoveryPanel.vue';
import {useCustomerWork} from '@/composables/useCustomerWork';
import {useCustomerWorkWriteoffOperations} from '@/composables/useCustomerWorkWriteoffOperations';
import {writeoffId,customerWriteoffNotice,customerWriteoffTerminal,customerWriteoffTime} from '@/utils/customerWorkWriteoff';
import type {CustomerWorkWriteoffCart} from '@/types/customerWorkWriteoff';
const orderId=ref(0),orderNo=ref(''),legacyId=ref(''),quantities=ref<Record<number,number>>({}),error=ref('');
const manager=useCustomerWork({page:'writeoff',query(q){legacyId.value=q.legacyOrderId??'';orderId.value=Number(q.orderId??0);orderNo.value=q.orderNo??'';},clear(){quantities.value={};error.value='';writeoff.clearDomain();},async load(controller){if(!writeoff.readable())throw Error('当前普通客户核销查询入口不可用');const valid=controller.fence(),basis=legacyId.value?await writeoff.resolveLegacy(legacyId.value):await writeoff.loadTarget(orderId.value,orderNo.value);if(valid())await writeoff.checkRelevant(basis.root_order_id);}}),writeoff=useCustomerWorkWriteoffOperations(manager),target=computed(()=>writeoff.target.value?.data??null),selected=computed(()=>Object.entries(quantities.value).filter(([,n])=>n>0).map(([id,n])=>({cart_row_id:Number(id),writeoff_num:n})).sort((a,b)=>a.cart_row_id-b.cart_row_id)),total=computed(()=>selected.value.reduce((sum,item)=>sum+item.writeoff_num,0)),allSelected=computed(()=>!!target.value&&target.value.carts.filter(r=>r.write_surplus_times>0).every(r=>quantities.value[r.cart_row_id]===r.write_surplus_times));
// Busy updates and equal-valued object replacements must not reset the user's draft.
watch([()=>target.value?.id,()=>target.value?.order_no,()=>target.value?.order_revision,()=>target.value?.writeoff_revision,()=>target.value?.target_fingerprint],()=>{quantities.value={};error.value='';},{flush:'sync'});
function inWindow(item:CustomerWorkWriteoffCart){const now=Math.floor(Date.now()/1000);return (!item.write_start||item.write_start<=now)&&(!item.write_end||item.write_end>=now);}
function selectable(item:CustomerWorkWriteoffCart){return !writeoff.busy.value&&target.value?.actions.writeoff.available&&item.write_surplus_times>0&&item.is_writeoff===0&&item.sale_price.source!=='unproven'&&inWindow(item);}
function toggle(item:CustomerWorkWriteoffCart){if(!selectable(item))return;quantities.value={...quantities.value,[item.cart_row_id]:quantities.value[item.cart_row_id]?0:1};error.value='';}
function change(item:CustomerWorkWriteoffCart,delta:number){if(!selectable(item))return;const next=(quantities.value[item.cart_row_id]||0)+delta;if(!writeoffId(next)||next>item.write_surplus_times)return;quantities.value={...quantities.value,[item.cart_row_id]:next};error.value='';}
function set(item:CustomerWorkWriteoffCart,event:unknown){if(!selectable(item))return;const detail=event&&typeof event==='object'&&'detail' in event?event.detail:undefined,raw=detail&&typeof detail==='object'&&'value' in detail?detail.value:undefined;if(typeof raw!=='string'||!(/^(0|[1-9]\d{0,9})$/u.test(raw))||!writeoffId(Number(raw),0)||Number(raw)>item.write_surplus_times){error.value='本次次数须为不超过实际剩余次数的整数，尚未修改';return;}quantities.value={...quantities.value,[item.cart_row_id]:Number(raw)};error.value='';}
function selectAll(){if(writeoff.busy.value||!target.value?.actions.writeoff.available)return;quantities.value=Object.fromEntries(target.value.carts.filter(selectable).map(item=>[item.cart_row_id,item.write_surplus_times]));error.value='';}
async function execute(){const basis=target.value;if(!basis||writeoff.busy.value||error.value)return;if(selected.value.some(item=>!basis.carts.some(row=>row.cart_row_id===item.cart_row_id&&selectable(row)))){error.value='所选商品的次数或有效窗口已变化，请重新读取';return;}const valid=manager.fence(),result=await writeoff.submit(basis,selected.value);if(!valid()||!result)return;const key=result.receipt?.request_key??writeoff.pending.value.find(i=>i.body.order_id===basis.id)?.request_key;if(result.receipt&&customerWriteoffTerminal(result))quantities.value={};if(key)manager.go('writeoffResult',{requestKey:key});}
</script>
<style scoped>.cw-quantity input{width:130rpx;min-width:0;text-align:center}</style>
